function fewestCheckpoints(trips: number[][]): number {
  const t = [...trips].sort((a, b) => a[0] - b[0]);
  let count = 1, groupEnd = t[0][1];
  for (let i = 1; i < t.length; i++) {
    if (t[i][0] > groupEnd) { count++; groupEnd = t[i][1]; }
    else groupEnd = Math.min(groupEnd, t[i][1]);
  }
  return count;
}

