class Solution:
    def fewestCheckpoints(self, trips: List[List[int]]) -> int:
        t = sorted(trips)
        count, group_end = 1, t[0][1]
        for s, e in t[1:]:
            if s > group_end:
                count += 1
                group_end = e
            else:
                group_end = min(group_end, e)
        return count

