function fewestCheckpoints(trips: number[][]): number {
  const t = [...trips].sort((a, b) => a[1] - b[1]);
  let count = 0, last = -Infinity;
  for (const [s, e] of t) {
    if (s > last) { count++; last = e; }
  }
  return count;
}

